/**
 * The local workspace map (`<config>/workspaces.json`, copied from `workspaces.example.json`), shared
 * by the hook that announces the ALM target at session start (workspace-context.js) and the one that
 * pins the Azure CLI identity on a command (lib/az-pin.js), so both resolve a directory the same
 * way: the longest root whose path contains it, case-insensitively.
 *
 * Pure file reads, no network, no `az`. `readRoots` throws on a missing or malformed map: each caller
 * decides what that means (silence, for both).
 *
 * Generated by Claude Code at the user's request.
 */

'use strict';

const fs = require('fs');
const os = require('os');
const path = require('path');

const { CONFIG_DIR } = require('./cache');

/** Every root of the map, longest path first, each with its lowercased absolute `root`. */
function readRoots() {
  const roots = JSON.parse(fs.readFileSync(path.join(CONFIG_DIR, 'workspaces.json'), 'utf8'))?.roots;
  if (!Array.isArray(roots)) throw new Error('no roots');
  return roots
    .filter((r) => r && typeof r.path === 'string')
    .map((r) => ({ ...r, root: path.resolve(r.path).toLowerCase() }))
    .sort((a, b) => b.root.length - a.root.length);
}

/** A directory in the form `matchRoot` compares: absolute and lowercased. */
const resolveDir = (cwd) => path.resolve(cwd || process.cwd()).toLowerCase();

/** The root containing `dir` (already through `resolveDir`), else undefined. */
const matchRoot = (roots, dir) => roots.find(({ root }) => dir === root || dir.startsWith(root + path.sep));

/** The private Azure CLI config dir of a root's `identity` (`~/.azure-<identity>`), null when it has none or it is absent. */
function azConfigDir(entry) {
  if (!/^[\w.-]+$/.test(entry?.identity ?? '')) return null;
  const dir = path.join(os.homedir(), `.azure-${entry.identity}`);
  return fs.existsSync(dir) ? dir : null;
}

module.exports = { CONFIG_DIR, readRoots, resolveDir, matchRoot, azConfigDir };
